    heroHeadline: "ଦ୍ରୁତ, ସୁରକ୍ଷିତ ଟ୍ରାଏଜ୍ ନୋଟ୍ — ପ୍ରତ୍ୟେକ ଥର ଡାକ୍ତରଙ୍କ ଦ୍ୱାରା ଯାଞ୍ଚ।",
    heroDescription: "ସ୍ୱାସ୍ଥ୍ୟ ସଖୀ କଥିତ ଲକ୍ଷଣ, ଲିଖିତ ଟିପ୍ପଣୀ, ଲାବ୍ ରିପୋର୍ଟ ଏବଂ ଫଟୋକୁ ରୋଗୀଙ୍କ ନିଜ ଭାଷାରେ ଏକ ଗଠନମୂଳକ ଟ୍ରାଏଜ୍ ନୋଟ୍‌ରେ ପରିଣତ କରେ — ଯାହାଫଳରେ ସ୍ୱାସ୍ଥ୍ୟକର୍ମୀ ଓ ଡାକ୍ତରମାନେ ଭିଡ଼ ଥିବା ଲାଇନକୁ ଆତ୍ମବିଶ୍ୱାସ ସହିତ ସମୀକ୍ଷା କରିପାରିବେ।",
