    workflowTitle: "ସହାୟକ ପ୍ରସ୍ତୁତ କରେ। ଯୋଗ୍ୟ ଚିକିତ୍ସକ ନିଷ୍ପତ୍ତି ନିଅନ୍ତି।",
    workflowDesc: "ପ୍ରତ୍ୟେକ ପଦକ୍ଷେପ ଚିକିତ୍ସକଙ୍କ ସମୟ ବଞ୍ଚାଇବା ଏବଂ ସମ୍ପୂର୍ଣ୍ଣ ଡାକ୍ତରୀ ଯାଞ୍ଚ ସୁନିଶ୍ଚିତ କରିବା ପାଇଁ ଡିଜାଇନ୍ କରାଯାଇଛି।",
    workflowStep1Title: "୧. ଲକ୍ଷଣ ସଂଗ୍ରହ",
    workflowStep1Body: "ରୋଗୀ କିମ୍ବା ଆଶା/ANM ନିଜ ଭାଷାରେ ଲକ୍ଷଣ କୁହନ୍ତି ବା ଲେଖନ୍ତି। ଯେକୌଣସି ଫୋନରୁ ରିପୋର୍ଟ ଏବଂ ଫଟୋ ଅପଲୋଡ୍ କରାଯାଇପାରିବ।",
    workflowStep2Title: "୨. ତଥ୍ୟ ବାହାର କରିବା",
    workflowStep2Body: "OCR ଲାବ୍ ମୂଲ୍ୟ ପଢ଼େ, ସ୍ୱର ଲିପ୍ୟନ୍ତରଣ ଏବଂ ଅନୁବାଦ ହୁଏ, ଏବଂ ପ୍ରତ୍ୟେକ ତଥ୍ୟ ନିଜର ମୂଳ ଉତ୍ସ ସହ ଯୋଡ଼ି ହୋଇ ରହେ।",
    workflowStep3Title: "୩. ସଜାଇବା",
    workflowStep3Body: "ସ୍ୱାସ୍ଥ୍ୟ ଇତିହାସ, ଜରୁରୀ ସଙ୍କେତ, ବାକି ଥିବା ତଥ୍ୟ ଏବଂ ସମ୍ଭାବ୍ୟ ପ୍ରଶ୍ନ ସହିତ ଏକ ସଂଗଠିତ ନୋଟ୍।",
    workflowStep4Title: "୪. ମାନବୀୟ ସମୀକ୍ଷା",
    workflowStep4Body: "ନର୍ସ ବା ଡାକ୍ତର ଯାଞ୍ଚ କରନ୍ତି, ସଂଶୋଧନ କରନ୍ତି ଓ ସ୍ୱାକ୍ଷର କରନ୍ତି। ଡାକ୍ତରଙ୍କ ଅନୁମୋଦନ ବିନା କିଛି ଚୂଡ଼ାନ୍ତ ନୁହେଁ।",
    workflowStep5Title: "୫. ପ୍ରାଥମିକତା ବା ରେଫରାଲ୍",
    workflowStep5Body: "ଜରୁରୀକାଳୀନ ମାମଲା ଆଗୁଆ ଧାଡ଼ିକୁ ଯାଏ। ଉଚ୍ଚ ସ୍ୱାସ୍ଥ୍ୟକେନ୍ଦ୍ର ପାଇଁ ରେଫରାଲ୍ ସ୍ଲିପ୍ ପ୍ରସ୍ତୁତ ହୋଇ ଡାକ୍ତରଙ୍କ ଯାଞ୍ଚ ପାଇଁ ରହେ।",
    capabilitiesBadge: "ବହୁମୁଖୀ ଡିଜାଇନ୍",
    capabilitiesTitle: "ରୋଗୀ ଯାହା ଆଣନ୍ତି, ତାହା ସହ କାମ କରେ।",
    capabilitiesDesc: "ଏକ ମୋଡ଼ା ହୋଇଥିବା ଲାବ୍ ରିପୋର୍ଟ, ଓଡ଼ିଆ କିମ୍ବା ହିନ୍ଦୀରେ ଭଏସ୍ ନୋଟ୍, ବା ଫୋନ୍ ଫଟୋ — ସ୍ୱାସ୍ଥ୍ୟ ସଖୀ ଏହାକୁ ଏକ ମିନିଟ୍ ମଧ୍ୟରେ ଯାଞ୍ଚଯୋଗ୍ୟ ସ୍ପଷ୍ଟ ନୋଟ୍‌ରେ ପରିଣତ କରେ।",
    capVoiceTitle: "ଭଏସ୍ ଇନପୁଟ୍",
    capVoiceBody: "ଓଡ଼ିଆ, ହିନ୍ଦୀ, ବଙ୍ଗଳା ଏବଂ ଅନ୍ୟାନ୍ୟ ଭାଷାରେ ଲକ୍ଷଣ ରେକର୍ଡ କରନ୍ତୁ। ଯାଞ୍ଚ ପାଇଁ ମୂଳ ଅଡିଓ ଏବଂ ଲିଖିତ ତଥ୍ୟ ସୁରକ୍ଷିତ ରହେ।",
    capOcrTitle: "ଲାବ୍ ରିପୋର୍ଟ OCR",
    capOcrBody: "ଛାପା ବା ଫଟୋ ଉଠାଯାଇଥିବା ରିପୋର୍ଟରୁ ପରୀକ୍ଷା ନାମ, ସଂଖ୍ୟାତ୍ମକ ମୂଲ୍ୟ ଏବଂ ରେଫରେନ୍ସ ପରିସର ସଠିକତା ସହ ବାହାର କରେ।",
    capVisualTitle: "ଦୃଶ୍ୟ ଇନପୁଟ୍",
    capVisualBody: "ଘା' କିମ୍ବା ଫୁଲା ଫଟୋର ନିରପେକ୍ଷ ବର୍ଣ୍ଣନା କରାଯାଇ ନୋଟ୍‌ରେ ଯୋଡ଼ାଯାଏ — କେବେ ଚୂଡ଼ାନ୍ତ ରୋଗ ନିର୍ଣ୍ଣୟ କରେ ନାହିଁ।",
    capTranslationTitle: "ଦ୍ୱିମୁଖୀ ଅନୁବାଦ",
    capTranslationBody: "ଚିକିତ୍ସକଙ୍କ ପ୍ରଶ୍ନ ଉଭୟ ଇଂରାଜୀ ଏବଂ ସ୍ଥାନୀୟ ଭାଷାରେ ପ୍ରସ୍ତୁତ ହୁଏ, ଯାହାକୁ ସିଧାସଳଖ ପଢ଼ି ଶୁଣାଇ ହେବ।",
    capQueueTitle: "ଧାଡ଼ି ପ୍ରାଥମିକତା",
    capQueueBody: "ଜରୁରୀ, ପ୍ରାଥମିକତା ଏବଂ ସାଧାରଣ ବର୍ଗୀକରଣ ସହିତ ସ୍ପଷ୍ଟ କାରଣ ଯାହାଦ୍ୱାରା ଗୁରୁତର ରୋଗୀ ପ୍ରଥମେ ଦେଖାଯାଇପାରିବେ।",
