    safetyDesc: "ସୁରକ୍ଷା, ନୈତିକ ନିୟମାବଳୀ ଏବଂ ଡାକ୍ତରୀ ସ୍ୱଚ୍ଛତା ପାଇଁ ସ୍ୱତନ୍ତ୍ର ଭାବରେ ପ୍ରସ୍ତୁତ।",
    safetyRule1Title: "ନିଦାନ ବା ଔଷଧ ନିର୍ଦ୍ଧାରଣ କରେ ନାହିଁ",
    safetyRule1Body: "ସହାୟକର ଫଳାଫଳ କେବଳ ସାରାଂଶ, ଜରୁରୀ ସଙ୍କେତ ଏବଂ ପ୍ରଶ୍ନ ମଧ୍ୟରେ ସୀମିତ। ଚିକିତ୍ସା ବା ରୋଗ ନିର୍ଣ୍ଣୟ ବାରଣ କରାଯାଇଛି।",
    safetyRule2Title: "ବାଧ୍ୟତାମୂଳକ ମାନବୀୟ ସ୍ୱାକ୍ଷର",
    safetyRule2Body: "ପ୍ରତ୍ୟେକ ନୋଟ୍, ପ୍ରାଥମିକତା ବୃଦ୍ଧି ଏବଂ ରେଫରାଲ୍ ସ୍ଲିପ୍ ପାଇଁ ପ୍ରମାଣିତ ଡାକ୍ତର ବା ନର୍ସଙ୍କ PIN ଓ ସ୍ୱାକ୍ଷର ଆବଶ୍ୟକ।",
    safetyRule3Title: "ଉତ୍ସ ସହ ଯୋଡ଼ା ଏବଂ ସ୍ପଷ୍ଟୀକରଣଯୋଗ୍ୟ",
    safetyRule3Body: "ପ୍ରତ୍ୟେକ ତଥ୍ୟ ଅଡିଓ ରେକର୍ଡିଂ, ରିପୋର୍ଟ ଲାଇନ୍ ବା ଫଟୋ ସହ ସଠିକତା ସ୍କୋର ସହିତ ଯୋଡ଼ି ହୋଇ ରହିଥାଏ।",
    safetyRule4Title: "ସ୍ପଷ୍ଟ ଡିଜିଟାଲ୍ ସମ୍ମତି ପ୍ରଥମେ",
    safetyRule4Body: "ସମ୍ବେଦନଶୀଳ ତଥ୍ୟ ବିଶ୍ଳେଷଣ ପୂର୍ବରୁ ରୋଗୀଙ୍କ ନିଜ ଭାଷାରେ ସମ୍ମତି ନିଆଯାଏ।",
    safetyRule5Title: "DPDP ନିୟମ ଅନୁରୂପ",
    safetyRule5Body: "ତଥ୍ୟ ସୁରକ୍ଷା, ଏନକ୍ରିପସନ୍, ଭୂମିକା-ଆଧାରିତ ପ୍ରବେଶ ଏବଂ ଗୋପନୀୟତା ଅଡିଟ୍ ଲଗ୍‌ର ପାଳନ।",
    safetyRule6Title: "ସମ୍ପୂର୍ଣ୍ଣ ଅଡିଟ୍ ଟ୍ରେଲ୍",
    safetyRule6Body: "ପ୍ରତ୍ୟେକ ପରିଦର୍ଶନ, ସମୀକ୍ଷା ଏବଂ ରେଫରାଲ୍ ସଠିକ୍ ସମୟ ଓ କର୍ମଚାରୀ ବିବରଣୀ ସହ ରେକର୍ଡ ହୁଏ।",
    footerPlatform: "ସ୍ୱାସ୍ଥ୍ୟ ସଖୀ — ବହୁମୁଖୀ ଚିକିତ୍ସା ନିଷ୍ପତ୍ତି ସହାୟକ ମଞ୍ଚ",
    footerFacilityDesc: "PHC, CHC, ଜିଲ୍ଲା ଡାକ୍ତରଖାନା ଏବଂ ଶିଳ୍ପ ସ୍ୱାସ୍ଥ୍ୟ ୟୁନିଟ୍ ନିମନ୍ତେ। ଚିକିତ୍ସକଙ୍କ ଦ୍ୱାରା ଯାଞ୍ଚକୃତ।",
