    workflowStep2Body: "ওসিআর ল্যাব মান পড়ে, ভয়েস প্রতিলিপি এবং অনুবাদ হয়, এবং প্রতিটি তথ্য তার মূল উৎসের সাথে যুক্ত থাকে।",
    workflowStep3Title: "৩. তথ্য বিন্যাস",
    workflowStep3Body: "স্বাস্থ্য ইতিহাস, জরুরি সংকেত, অনুপস্থিত তথ্য এবং প্রস্তাবিত প্রশ্নাবলীর সাথে একটি সুবিন্যস্ত নোট।",
    workflowStep4Title: "৪. মানবিক পর্যালোচনা",
    workflowStep4Body: "একজন নার্স বা চিকিৎসক পর্যালোচনা, সম্পাদনা এবং স্বাক্ষর করেন। চিকিৎসকের অনুমোদন ছাড়া কোনো সিদ্ধান্ত চূড়ান্ত নয়।",
    workflowStep5Title: "৫. অগ্রাধিকার বা রেফারেল",
    workflowStep5Body: "জরুরি ক্ষেত্রগুলো সারিতে অগ্রাধিকার পায়। উচ্চতর কেন্দ্রের জন্য রেফারেল স্লিপ তৈরি করে চিকিৎসকের অনুমোদনের জন্য রাখা হয়।",
    capabilitiesBadge: "মাল্টিমোডাল ডিজাইন",
