    heroFacilityBadge: "PHC, CHC, மாவட்ட மருத்துவமனைகள் மற்றும் தொழிலக சுகாதாரப் பிரிவுகளுக்கு",
    heroHeadline: "வேகமான, பாதுகாப்பான ட்ரையேஜ் குறிப்புகள் — ஒவ்வொரு முறையும் மருத்துவரால் மதிப்பாய்வு செய்யப்படுகிறது.",
    heroDescription: "சுவாஸ்த்ய சகி பேசப்படும் அறிகுறிகள், எழுதப்பட்ட குறிப்புகள், ஆய்வக அறிக்கைகள் மற்றும் புகைப்படங்களை நோயாளியின் மொழியிலேயே கட்டமைக்கப்பட்ட ட்ரையேஜ் குறிப்புகளாக மாற்றுகிறது.",
