    workflowDesc: "மருத்துவரின் நேரத்தை மிச்சப்படுத்துவதோடு முழுமையான பொறுப்புணர்வை உறுதிசெய்யும் வகையில் வடிவமைக்கப்பட்டுள்ளது.",
    workflowStep1Title: "1. அறிகுறிகள் பதிவு",
    workflowStep1Body: "நோயாளி அல்லது ஆஷா/ANM தங்கள் சொந்த மொழியில் அறிகுறிகளைப் பேசுகிறார்கள் அல்லது எழுதுகிறார்கள்.",
    workflowStep2Title: "2. தகவல் பிரித்தெடுத்தல்",
    workflowStep2Body: "OCR ஆய்வக மதிப்புகளைப் படிக்கிறது, குரல் மொழிபெயர்க்கப்படுகிறது, மேலும் ஒவ்வொரு தகவலும் மூலத்துடன் இணைக்கப்படுகிறது.",
    workflowStep3Title: "3. ஒழுங்கமைத்தல்",
    workflowStep3Body: "சுகாதார வரலாறு, அவசர சிக்னல்கள் மற்றும் தொடர் கேள்விகளுடன் கூடிய கட்டமைக்கப்பட்ட குறிப்பு.",
    workflowStep4Title: "4. மனித மதிப்பாய்வு",
    workflowStep4Body: "செவிலியர் அல்லது மருத்துவர் சரிபார்த்து கையொப்பமிடுகிறார். மருத்துவரின் ஒப்புதல் இல்லாமல் எதுவும் முடிவடையாது.",
    workflowStep5Title: "5. முன்னுரிமை அல்லது பரிந்துரை",
    workflowStep5Body: "அவசர வழக்குகள் வரிசையில் முன்னுரிமை பெறுகின்றன. உயர் மையங்களுக்கான பரிந்துரை குறிப்பு தயாரிக்கப்படுகிறது.",
    capabilitiesBadge: "மல்டிமாடல் வடிவமைப்பு",
    capabilitiesTitle: "நோயாளி கொண்டு வரும் அனைத்து தகவல்களுடனும் செயல்படுகிறது.",
    capabilitiesDesc: "ஒரு ஆய்வக சீட்டு, குரல் பதிவு அல்லது புகைப்படம் — சுவாஸ்த்ய சகி ஒரு நிமிடத்தில் மதிப்பாய்வு செய்யக்கூடிய குறிப்பை உருவாக்குகிறது.",
    capVoiceTitle: "குரல் உள்ளீடு",
    capVoiceBody: "தமிழ், இந்தி மற்றும் பிற மொழிகளில் அறிகுறிகளை பதிவு செய்யுங்கள். சரிபார்ப்புக்கு ஆடியோ மற்றும் உரை இரண்டும் சேமிக்கப்படுகிறது.",
    capOcrTitle: "ஆய்வக அறிக்கை OCR",
    capOcrBody: "அறிக்கைகளிலிருந்து சோதனைப் பெயர்கள், எண்களை துல்லியமாக பிரித்தெடுக்கிறது.",
    capVisualTitle: "காட்சி உள்ளீடு",
    capVisualBody: "தடிப்புகள் அல்லது காயங்களின் புகைப்படங்கள் புறநிலையாக விவரிக்கப்பட்டு குறிப்பில் இணைக்கப்படுகின்றன.",
    capTranslationTitle: "இருவழி மொழிபெயர்ப்பு",
    capTranslationBody: "மருத்துவரின் கேள்விகள் ஆங்கிலம் மற்றும் உள்ளூர் மொழி இரண்டிலும் தயாராகிறது.",
    capQueueTitle: "வரிசை முன்னுரிமை",
    capQueueBody: "அவசர, முன்னுரிமை மற்றும் வழக்கமான பிரிவுகளுடன் நோயாளிகள் வரிசைப்படுத்தப்படுகிறார்கள்.",
