    safetyBadge: "பொறுப்பான AI கட்டுப்பாடுகள்",
    safetyTitle: "மருத்துவர்களும் நோயாளிகளும் நம்பக்கூடிய பாதுகாப்பு வழிகாட்டுதல்கள்.",
    safetyDesc: "பாதுகாப்பு, நெறிமுறை மற்றும் மருத்துவ வெளிப்படைத்தன்மையுடன் வடிவமைக்கப்பட்டது.",
