    safetyRule3Title: "மூலத்துடன் இணைக்கப்பட்டது",
    safetyRule3Body: "ஒவ்வொரு தகவலும் அசல் ஆடியோ, அறிக்கை வரி அல்லது புகைப்படத்துடன் இணைக்கப்பட்டுள்ளது.",
    safetyRule4Title: "முன்கூட்டியே டிஜிட்டல் ஒப்புதல்",
    safetyRule4Body: "தகவல்களை பகுப்பாய்வு செய்வதற்கு முன் நோயாளியின் சொந்த மொழியில் ஒப்புதல் பெறப்படுகிறது.",
