    heroDescription: "സ്വാസ്ഥ്യ സഖി പറയുന്ന ലക്ഷണങ്ങൾ, കുറിപ്പുകൾ, ലാബ് റിപ്പോർട്ടുകൾ, ഫോട്ടോകൾ എന്നിവ രോഗിയുടെ ഭാഷയിൽ ചിട്ടപ്പെടുത്തിയ ട്രയാജ് നോട്ടാക്കി മാറ്റുന്നു — ആരോഗ്യ പ്രവർത്തകർക്കും ഡോക്ടർമാർക്കും തിരക്ക് കൃത്യമായി കൈകാര്യം ചെയ്യാൻ സഹായിക്കുന്നു.",
