    workflowTitle: "സഹായി തയ്യാറാക്കുന്നു. യോഗ്യനായ ഡോക്ടർ തീരുമാനിക്കുന്നു.",
    workflowDesc: "ഡോക്ടറുടെ സമയം ലാഭിക്കുന്നതിനും പൂർണ്ണ നിരീക്ഷണക്ഷമത ഉറപ്പാക്കുന്നതിനുമായി രൂപകൽപ്പന ചെയ്തിരിക്കുന്നു.",
    workflowStep1Title: "1. വിവര ശേഖരണം",
