    capabilitiesDesc: "ഒരു ലാബ് കുറിപ്പ്, മലയാളത്തിലോ ഹിന്ദിയിലോ ഉള്ള വോയ്‌സ് നോട്ട് അല്ലെങ്കിൽ ഫോട്ടോ — സ്വാസ്ഥ്യ സഖി ഒരു മിനിറ്റിനുള്ളിൽ വ്യക്തമായ കുറിപ്പ് തയ്യാറാക്കുന്നു.",
