    workflowDesc: "ਹਰ ਕਦਮ ਡਾਕਟਰ ਦਾ ਸਮਾਂ ਬਚਾਉਣ ਅਤੇ ਮਨੁੱਖੀ ਤਸਦੀਕ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਬਣਾਇਆ ਗਿਆ ਹੈ।",
