    workflowDesc: "প্ৰতিটো পদক্ষেপ চিকিৎসকৰ সময় ৰাহি কৰিবলৈ আৰু মানৱীয় নিৰীক্ষণ নিশ্চিত কৰিবলৈ তৈয়াৰ কৰা হৈছে।",
