    workflowStep4Title: "৪. মানৱীয় পৰ্যালোচনা",
    workflowStep4Body: "নাৰ্ছ বা চিকিৎসকে পৰীক্ষা কৰে, সম্পাদনা কৰে আৰু স্বাক্ষৰ কৰে। চিকিৎসকৰ অনুমতি অবিহনে একো চূড়ান্ত নহয়।",
